/* column reduction + reduction transfer + Dijkstra shortest augmenting paths (Jonker-Volgenant) */
int lapjv(int n, const double *c, int *x, int *y){
  double *v=malloc(n*sizeof(double)), *d=malloc(n*sizeof(double));
  int *fr=malloc(n*sizeof(int)), *col=malloc(n*sizeof(int)), *pred=malloc(n*sizeof(int)), *matches=calloc(n,sizeof(int));
  int i,j,k;
  for(i=0;i<n;i++) x[i]=-1;
  for(j=0;j<n;j++) v[j]=DBL_MAX;
  int *imn=malloc(n*sizeof(int));
  for(i=0;i<n;i++){const double*ci=c+(long)i*n; for(j=0;j<n;j++) if(ci[j]<v[j]){v[j]=ci[j];imn[j]=i;}}
  for(j=n-1;j>=0;j--){ int im=imn[j]; if(++matches[im]==1){x[im]=j;y[j]=im;} else y[j]=-1; }
  free(imn);
  int nf=0;
  for(i=0;i<n;i++){
    if(matches[i]==0) fr[nf++]=i;
    else if(matches[i]==1){
      int j1=x[i]; double m=DBL_MAX; const double *ci=c+(long)i*n;
      for(j=0;j<n;j++) if(j!=j1){double h=ci[j]-v[j]; if(h<m)m=h;}
      if(m<DBL_MAX) v[j1]-=m;
    }
  }
  for(int f=0;f<nf;f++){
    int f0=fr[f], low=0, up=0, last=0, end=-1; double mn=0;
    const double *cf=c+(long)f0*n;
    for(j=0;j<n;j++){d[j]=cf[j]-v[j];pred[j]=f0;col[j]=j;}
    for(;;){
      if(up==low){
        last=low; mn=d[col[up++]];
        for(k=up;k<n;k++){j=col[k];double h=d[j];
          if(h<=mn){ if(h<mn){up=low;mn=h;} col[k]=col[up]; col[up++]=j; }}
        for(k=low;k<up;k++) if(y[col[k]]<0){end=col[k];break;}
        if(end>=0) break;
      }
      int j1=col[low++]; i=y[j1];
      const double *ci=c+(long)i*n;
      double u1=ci[j1]-v[j1]-mn;
      for(k=up;k<n;k++){j=col[k];double h=ci[j]-v[j]-u1;
        if(h<d[j]){d[j]=h;pred[j]=i;
          if(h==mn){ if(y[j]<0){end=j;break;} col[k]=col[up]; col[up++]=j; } } }
      if(end>=0) break;
    }
    for(k=0;k<last;k++){int j1=col[k]; v[j1]+=d[j1]-mn;}
    for(;;){ i=pred[end]; y[end]=i; int j1=end; end=x[i]; x[i]=j1; if(i==f0) break; }
  }
  free(v);free(d);free(fr);free(col);free(pred);free(matches);
  return 0;
}
