#include <stdlib.h>
#include <float.h>
/* Sparse SSP for square LAP. CSR: rowptr[n+1], cols, cst. Outputs x (row->col), v (column duals).
   Returns 0 on success, -1 if infeasible. */
typedef struct {double d; int j;} HE;
static void hpush(HE*h,int*sz,double d,int j){int i=(*sz)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int i=0,n=*sz;for(;;){int l=2*i+1;if(l>=n)break;int r=l+1;int m=(r<n&&h[r].d<h[l].d)?r:l;if(h[m].d>=last.d)break;h[i]=h[m];i=m;}if(n>0)h[i]=last;return top;}
int splap(int n,const int*rowptr,const int*cols,const double*cst,int*x,double*v){
  int nnz=rowptr[n];
  int *y=malloc(n*sizeof(int)),*pred=malloc(n*sizeof(int)),*state=calloc(n,sizeof(int)),*touched=malloc(n*sizeof(int)),*scanned=malloc(n*sizeof(int));
  double *d=malloc(n*sizeof(double)); HE*h=malloc((nnz+n+8)*sizeof(HE));
  double *xc=malloc(n*sizeof(double)); /* cost of assigned edge */
  int i,j,k;
  for(j=0;j<n;j++){y[j]=-1;v[j]=0;}
  for(i=0;i<n;i++) x[i]=-1;
  /* greedy init: row argmin if free (v=0 so consistent) */
  for(i=0;i<n;i++){double m=DBL_MAX;int jm=-1;for(k=rowptr[i];k<rowptr[i+1];k++) if(cst[k]<m){m=cst[k];jm=cols[k];}
    if(jm>=0&&y[jm]<0){x[i]=jm;y[jm]=i;xc[i]=m;}}
  int ret=0;
  for(int f=0;f<n;f++){
    if(x[f]>=0) continue;
    int nt=0,ns=0,sz=0,end=-1; double dmin=0;
    /* state: 0 untouched,1 in heap(touched),2 scanned */
    for(k=rowptr[f];k<rowptr[f+1];k++){j=cols[k];double dd=cst[k]-v[j];
      if(state[j]==0){state[j]=1;touched[nt++]=j;d[j]=dd;pred[j]=f;hpush(h,&sz,dd,j);}
      else if(dd<d[j]){d[j]=dd;pred[j]=f;hpush(h,&sz,dd,j);} }
    while(sz>0){
      HE e=hpop(h,&sz); j=e.j;
      if(state[j]==2||e.d>d[j]) continue;
      if(y[j]<0){end=j;dmin=e.d;break;}
      state[j]=2; scanned[ns++]=j;
      i=y[j]; double base=e.d-(xc[i]-v[j]);
      for(k=rowptr[i];k<rowptr[i+1];k++){int jj=cols[k]; if(state[jj]==2) continue;
        double dd=base+cst[k]-v[jj];
        if(state[jj]==0){state[jj]=1;touched[nt++]=jj;d[jj]=dd;pred[jj]=i;hpush(h,&sz,dd,jj);}
        else if(dd<d[jj]){d[jj]=dd;pred[jj]=i;hpush(h,&sz,dd,jj);} }
    }
    if(end<0){ret=-1;break;}
    for(k=0;k<ns;k++){j=scanned[k]; v[j]+=d[j]-dmin;}
    for(k=0;k<nt;k++) state[touched[k]]=0;
    /* augment */
    j=end;
    for(;;){ i=pred[j]; int jprev=x[i]; y[j]=i; x[i]=j;
      /* find cost of edge (i,j) */
      for(k=rowptr[i];k<rowptr[i+1];k++) if(cols[k]==j){xc[i]=cst[k];break;}
      if(i==f) break; j=jprev; }
  }
  free(y);free(pred);free(state);free(touched);free(scanned);free(d);free(h);free(xc);
  return ret;
}
