#include <stdlib.h>
#include <string.h>
#include <float.h>
typedef struct {double d; int j;} HE;
static inline void hpush(HE*h,int*sz,double d,int j){int i=(*sz)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static inline HE hpop(HE*h,int*sz){HE top=h[0];HE last=h[--(*sz)];int i=0,n=*sz;for(;;){int l=2*i+1;if(l>=n)break;int r=l+1;int m=(r<n&&h[r].d<h[l].d)?r:l;if(h[m].d>=last.d)break;h[i]=h[m];i=m;}if(n>0)h[i]=last;return top;}

/* top-k smallest indices of a strided vector */
static void topk(const double*a,long stride,int n,int k,int*out){
  double bd[64]; int bi[64]; int cnt=0;
  for(int t=0;t<n;t++){double val=a[(long)t*stride];
    if(cnt<k){int p=cnt++;while(p>0&&bd[p-1]>val){bd[p]=bd[p-1];bi[p]=bi[p-1];p--;}bd[p]=val;bi[p]=t;}
    else if(val<bd[k-1]){int p=k-1;while(p>0&&bd[p-1]>val){bd[p]=bd[p-1];bi[p]=bi[p-1];p--;}bd[p]=val;bi[p]=t;}}
  for(int t=0;t<cnt;t++) out[t]=bi[t];
}

/* Solve dense square LAP exactly using sparse candidate graph + dual verification.
   Returns 0 on success, nonzero on failure. x: row->col. */
int lap(int n,const double*c,int k,int*x){
