  int tmp[64]; int i,j,t,ret=0;
#define ADD(I,J) do{long _q=(long)(I)*n+(J); if(!in[_q]){in[_q]=1;adj[(long)(I)*n+deg[I]++]=(J);}}while(0)
  for(i=0;i<n;i++){topk(c+(long)i*n,1,n,k,tmp);for(t=0;t<k;t++)ADD(i,tmp[t]);}
  for(j=0;j<n;j++){topk(c+j,n,n,k,tmp);for(t=0;t<k;t++)ADD(tmp[t],j);}
  for(j=0;j<n;j++){v[j]=DBL_MAX;y[j]=-1;}
  for(i=0;i<n;i++){x[i]=-1;for(t=0;t<deg[i];t++){j=adj[(long)i*n+t];if(c[(long)i*n+j]<v[j])v[j]=c[(long)i*n+j];}}
  for(j=0;j<n;j++) if(v[j]==DBL_MAX) v[j]=0;
