    for(i=0;i<n;i++){const double*ci=c+(long)i*n;const int*ai=adj+(long)i*n;double m=DBL_MAX;int jm=-1;
      for(t=0;t<deg[i];t++){j=ai[t];double r=ci[j]-v[j];if(r<m){m=r;jm=j;}}
      u[i]=m;
      if(x[i]>=0){j=x[i]; if(ci[j]-v[j]-m>1e-13){y[j]=-1;x[i]=-1;}}
    }
    for(i=0;i<n;i++) if(x[i]<0){const double*ci=c+(long)i*n;const int*ai=adj+(long)i*n;
      for(t=0;t<deg[i];t++){j=ai[t];if(y[j]<0&&ci[j]-v[j]-u[i]<=1e-13){x[i]=j;y[j]=i;break;}}}
    for(int f=0;f<n;f++){
