        double base=e.d-(ci[j]-v[j]);
        for(t=0;t<deg[i];t++){int jj=ai[t]; if(state[jj]==2) continue;
          double dd=base+ci[jj]-v[jj];
          if(state[jj]==0){state[jj]=1;touched[nt++]=jj;d[jj]=dd;pred[jj]=i;hpush(h,&sz,dd,jj);}
          else if(dd<d[jj]){d[jj]=dd;pred[jj]=i;hpush(h,&sz,dd,jj);} }
      }
