      if(end<0){ret=1;goto done;}
      for(t=0;t<ns;t++){j=scanned[t]; v[j]+=d[j]-dmin;}
      j=end;
      for(;;){ i=pred[j]; int jp=x[i]; y[j]=i; x[i]=j; if(i==f) break; j=jp; }
    }
    /* verify on dense matrix */
    int nviol=0;
    for(i=0;i<n;i++){const double*ci=c+(long)i*n; double ui=ci[x[i]]-v[x[i]];
      for(j=0;j<n;j++) if(ci[j]-v[j]-ui< -1e-12){ long q=(long)i*n+j; if(!in[q]){in[q]=1;adj[(long)i*n+deg[i]++]=j;nviol++;} } }
    if(nviol==0){ret=0;goto done;}
  }
