import ctypes, os
import numpy as np
import ot

_dir = os.path.dirname(os.path.abspath(__file__))
_lib = ctypes.CDLL(os.path.join(_dir, "splap.so"))
_lib.lap.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p]
_lib.lap.restype = ctypes.c_int


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if (n == b.shape[0] and n > 0 and M.shape == (n, n)
                and np.all(a == a[0]) and np.all(b == a[0]) and np.all(np.isfinite(M))):
            x = np.empty(n, dtype=np.int32)
            r = _lib.lap(n, M.ctypes.data, kwargs.get("k", 10), x.ctypes.data)
            if r == 0:
                G = np.zeros((n, n))
                G[np.arange(n), x] = a[0]
                return {"transport_plan": G}
        G = ot.lp.emd(a, b, M, check_marginals=False)
        return {"transport_plan": G}
